      }
    ],
    "patient_family_realworld_adaptation": [
      {
        "event_id": "lite_evt_00233",
        "explanation": "The doctor adapted instructions to the sensitive body site and the patient's fear of manipulating the wound.",
        "quote": "不要扒开阴唇去找里面的伤口"
      }
    ]
  },
  "dimension_ratings": {
