  "high_order_assessment": [
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00211",
          "explanation": "The doctor explicitly corrected the earlier route advice and deferred to the doctor who examined the wound and records.",
          "quote": "她手里有你完整的出院记录，做出的判断**比我在没看到原单的情况下更准确**"
        },
        {
          "event_id": "lite_evt_00211",
          "explanation": "The correction was translated into a new safety plan.",
          "quote": "不再口服维E"
        }
      ],
      "completion": "complete",
